def improper(label,f,lo,hi,target,direction,key,kp,classification):
 op=f'limit(integrate({f},(x,{lo},{hi})),t,{target},dir="{direction}")'
 p=v(label,op,key,kp,'Start from the ORIGINAL integrand and replace its infinite/singular endpoint with finite t on the ACTUAL real-domain side. Integrate on that proper truncated interval,then take the explicit one-sided limit. Convergence requires a finite real limit;an infinite limit records divergence,not a finite numerical integral. Infinity is not treated as a real number and no division by0is performed.')
 p.update(assessed_8227_demand_ids=[IMPROPER],component_demand_ids=[INT],given_representation='text',response_format='numeric',original_integrand=f,truncated_bounds=[str(lo),str(hi)],limiting_endpoint=str(target),limit_direction=direction,printed_convergence=classification,author_convergence_basis='The independently computed limit is finite real exactly in the convergent cases. Values for divergent cases are directional limit diagnoses,not finite answers.')
 return p
