refs=[(60,350,'Infinity shorthand composite table','Read all five sections:addition,subtraction,multiplication,division,undefined operations. Interpret finite-coefficient statements as limiting/extended-real shorthand,not arithmetic with an infinitely large REAL number. Sign rules require the stated finite nonzero coefficient;0timesanunboundedvariable and∞−∞require separate analysis. No equation licenses dividing by0.',[IMPROPER],'table',[]),(61,351,'Convergent versus divergent improper-integral table','A finite real endpoint limit is convergent. Infinite or nonexistent limits are divergent;we can often establish divergence even though no finite integral exists. Do not call∞a finite evaluated answer.',[IMPROPER],'table',[]),(62,351,'Positive-infinite upper-bound prescription','Replace upper∞with finite t,then take t→+∞after a proper truncated integration. Every cutoff interval must preserve the original domain.',[IMPROPER],'table',[('limit(1-1/t,t,oo)','1')]),(63,351,'Negative-infinite lower-bound prescription','Replace lower−∞with finite t,then take t→−∞. The source native DOESprint the minus sign;the thumbnail suspicion is cleared. Preserve bound orientation.',[IMPROPER],'table',[('limit(-Rational(5,4)+5/t**2,t,-oo)','-Rational(5,4)')]),(64,352,'Singular lower-endpoint prescription','For a singular lower endpointa,replace it witht>aandapproachafromRIGHTthroughvalidtruncatedintervals. Finite/infinite limits determine convergence,not substitution1/0.',[IMPROPER],'table',[('limit(2-2*sqrt(t),t,0,dir="+")','2')]),(65,352,'Singular upper-endpoint prescription','For singularupperb,replace it witht<bandapproachbfromLEFT. Interior discontinuities would require independent splits;this elementary section only treats endpoint singularities.',[IMPROPER],'table',[('limit(-2*sqrt(3-t)+2*sqrt(3),t,3,dir="-")','2*sqrt(3)')])]
